import json
import os
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _bbox_from_polygon(polygon: Any) -> Optional[Dict[str, float]]:
    if not polygon:
        return None
    xs = []
    ys = []
    for p in polygon:
        x = getattr(p, "x", None)
        y = getattr(p, "y", None)
        if x is None or y is None:
            if isinstance(p, dict):
                x = p.get("x")
                y = p.get("y")
        if x is not None and y is not None:
            xs.append(float(x))
            ys.append(float(y))
    if not xs or not ys:
        return None
    return {"x1": min(xs), "y1": min(ys), "x2": max(xs), "y2": max(ys)}


def _span_text(content: str, spans: Any) -> str:
    if not content or not spans:
        return ""
    parts: List[str] = []
    for span in spans:
        offset = getattr(span, "offset", None)
        length = getattr(span, "length", None)
        if offset is None or length is None:
            if isinstance(span, dict):
                offset = span.get("offset")
                length = span.get("length")
        if offset is not None and length is not None:
            parts.append(content[int(offset) : int(offset) + int(length)])
    return "".join(parts)


def _normalize_result(result: Any) -> Dict[str, Any]:
    content = getattr(result, "content", "") or ""
    normalized: Dict[str, Any] = {
        "content": content,
        "pages": [],
        "paragraphs": [],
        "tables": [],
        "key_value_pairs": [],
        "styles": [],
    }

    for page in getattr(result, "pages", []) or []:
        page_info = {
            "page_number": getattr(page, "page_number", None),
            "width": getattr(page, "width", None),
            "height": getattr(page, "height", None),
            "unit": getattr(page, "unit", None),
            "lines": [],
            "words": [],
        }
        for line in getattr(page, "lines", []) or []:
            page_info["lines"].append(
                {
                    "content": getattr(line, "content", None) or _span_text(content, getattr(line, "spans", None)),
                    "polygon": _bbox_from_polygon(getattr(line, "polygon", None)),
                    "spans": [
                        {"offset": getattr(s, "offset", None), "length": getattr(s, "length", None)}
                        for s in (getattr(line, "spans", None) or [])
                    ],
                }
            )
        for word in getattr(page, "words", []) or []:
            page_info["words"].append(
                {
                    "content": getattr(word, "content", None),
                    "confidence": getattr(word, "confidence", None),
                    "polygon": _bbox_from_polygon(getattr(word, "polygon", None)),
                }
            )
        normalized["pages"].append(page_info)

    for para in getattr(result, "paragraphs", []) or []:
        normalized["paragraphs"].append(
            {
                "content": getattr(para, "content", None) or _span_text(content, getattr(para, "spans", None)),
                "role": getattr(para, "role", None),
                "polygon": _bbox_from_polygon(getattr(para, "bounding_regions", None)[0].polygon if getattr(para, "bounding_regions", None) else None),
                "spans": [
                    {"offset": getattr(s, "offset", None), "length": getattr(s, "length", None)}
                    for s in (getattr(para, "spans", None) or [])
                ],
            }
        )

    for table in getattr(result, "tables", []) or []:
        cells = []
        for cell in getattr(table, "cells", []) or []:
            cells.append(
                {
                    "row_index": getattr(cell, "row_index", None),
                    "column_index": getattr(cell, "column_index", None),
                    "row_span": getattr(cell, "row_span", None),
                    "column_span": getattr(cell, "column_span", None),
                    "content": getattr(cell, "content", None) or _span_text(content, getattr(cell, "spans", None)),
                    "kind": getattr(cell, "kind", None),
                    "polygon": _bbox_from_polygon(getattr(cell, "bounding_regions", None)[0].polygon if getattr(cell, "bounding_regions", None) else None),
                }
            )
        normalized["tables"].append(
            {
                "row_count": getattr(table, "row_count", None),
                "column_count": getattr(table, "column_count", None),
                "cells": cells,
            }
        )

    for kv in getattr(result, "key_value_pairs", []) or []:
        normalized["key_value_pairs"].append(
            {
                "key": {
                    "content": getattr(getattr(kv, "key", None), "content", None) if getattr(kv, "key", None) else None,
                    "polygon": _bbox_from_polygon(getattr(getattr(kv, "key", None), "bounding_regions", None)[0].polygon if getattr(getattr(kv, "key", None), "bounding_regions", None) else None),
                },
                "value": {
                    "content": getattr(getattr(kv, "value", None), "content", None) if getattr(kv, "value", None) else None,
                    "polygon": _bbox_from_polygon(getattr(getattr(kv, "value", None), "bounding_regions", None)[0].polygon if getattr(getattr(kv, "value", None), "bounding_regions", None) else None),
                },
            }
        )

    for style in getattr(result, "styles", []) or []:
        normalized["styles"].append(
            {
                "is_handwritten": getattr(style, "is_handwritten", None),
                "confidence": getattr(style, "confidence", None),
                "spans": [
                    {"offset": getattr(s, "offset", None), "length": getattr(s, "length", None)}
                    for s in (getattr(style, "spans", None) or [])
                ],
            }
        )

    return normalized


def extract_layout(document_path: str, model_id: str = "prebuilt-layout") -> Dict[str, Any]:
    endpoint = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY")
    if not endpoint or not key:
        raise ValueError(
            "AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY must be set"
        )

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document(model_id=model_id, body=f)
    result = poller.result()
    return _normalize_result(result)


def extract_layout_from_bytes(document_bytes: bytes, model_id: str = "prebuilt-layout") -> Dict[str, Any]:
    endpoint = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY")
    if not endpoint or not key:
        raise ValueError(
            "AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY must be set"
        )

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))
    poller = client.begin_analyze_document(model_id=model_id, body=document_bytes)
    result = poller.result()
    return _normalize_result(result)


def extract_layout_json(document_path: str) -> str:
    return json.dumps(extract_layout(document_path), ensure_ascii=False)
